// static
bool StructTraits<::arc::mojom::MountPointInfo::DataView, ::arc::mojom::MountPointInfoPtr>::Read(
    ::arc::mojom::MountPointInfo::DataView input,
    ::arc::mojom::MountPointInfoPtr* output) {
  bool success = true;
  ::arc::mojom::MountPointInfoPtr result(::arc::mojom::MountPointInfo::New());
  
      if (success && !input.ReadMountEvent(&result->mount_event))
        success = false;
      if (success && !input.ReadSourcePath(&result->source_path))
        success = false;
      if (success && !input.ReadMountPath(&result->mount_path))
        success = false;
      if (success && !input.ReadFsUuid(&result->fs_uuid))
        success = false;
      if (success && !input.ReadLabel(&result->label))
        success = false;
      if (success && !input.ReadDeviceType(&result->device_type))
        success = false;
      if (success)
        result->visible = input.visible();
  *output = std::move(result);
  return success;
}

